import * as T from './three.module.js';
// Small, local environment map supplies sky and ground reflections without downloads.
export function daylightReflections(){const faces=[];for(let i=0;i<6;i++){const c=document.createElement('canvas');c.width=c.height=256;const x=c.getContext('2d');const g=x.createLinearGradient(0,0,0,256);if(i===2){g.addColorStop(0,'#799bbc');g.addColorStop(1,'#c5dced');}else if(i===3){g.addColorStop(0,'#747566');g.addColorStop(1,'#55594d');}else{g.addColorStop(0,'#95b6d0');g.addColorStop(.48,'#edf3f5');g.addColorStop(.52,'#aaafa5');g.addColorStop(1,'#666c5d');}x.fillStyle=g;x.fillRect(0,0,256,256);if(i!==3){const glow=x.createRadialGradient(55,45,0,55,45,90);glow.addColorStop(0,'rgba(255,255,255,.75)');glow.addColorStop(1,'rgba(255,255,255,0)');x.fillStyle=glow;x.fillRect(0,0,256,256);}faces.push(c);}const env=new T.CubeTexture(faces);env.colorSpace=T.SRGBColorSpace;env.needsUpdate=true;return env;}
